class WftClient:
    def __init__(self, logger: logging.Logger) -> None:
        self.logger = logger

    def _make_wft_request(self, url: str, headers: Dict[str, str], data: Dict[str, Union[str, List[str]]], proxy: Optional[str] = None) -> Dict:
        """
        Makes a request to the WFT API.

        Args:
            url (str): The URL to make the request to.
            headers (Dict[str, str]): The headers to include in the request.
            data (Dict[str, Union[str, List[str]]]): The data to include in the request.
            proxy (Optional[str]): The proxy to use for the request, if any.

        Returns:
            Dict: The response from the WFT API, or an empty dictionary if the request fails.
        """
        empty_response: Dict = {}
        try:
            response = requests.get(url, timeout=5, verify=False, headers=headers, data=json.dumps(data),
                                    proxies={"http": proxy} if proxy else None)
        except requests.RequestException as exc:
            self.logger.warning('Cannot get contents from url {}, exception: {}'.format(url, exc))
            return empty_response
        if response.status_code == 200:
            try:
                response = response.json()
                return response
            except json.JSONDecodeError:
                self.logger.warning('Cannot get json contents from url {}'.format(url))
        self.logger.warning('Wrong response from WFT {}, status code: {}'.format(url, response.status_code))
        return empty_response

    def get_parent_build(self, build: str) -> Optional[str]:
        """
        Retrieves the parent build for a given build - the build parameters "based_on" is used.

        Args:
            build (str): The build identifier.

        Returns:
            Optional[str]: The parent build identifier, or None if not found.
        """
        data = self._make_wft_request(WFT_PARENT_BUILD_URL.format(build), WFT_HEADERS, WFT_PARENT_BUILD_DATA)
        return data.get("based_on")

    def check_build_exists(self, build: str) -> bool:
        """
        Checks if a build exists in WFT list.

        Args:
            build (str): The build identifier.

        Returns:
            bool: True if the build exists, False otherwise.
        """
        return bool(self._make_wft_request(WFT_BUILD_EXISTS_URL.format(build), WFT_HEADERS, WFT_PARENT_BUILD_DATA))

    def get_package_url(self, build: str, name: str) -> str:
        """
        Retrieves the URL of a package for a given build. The package is identified by its name like 'pstools.zip'.

        Args:
            build (str): The build identifier.
            name (str): The name of the package.

        Returns:
            str: The URL of the package, or an empty string if not found.
        """
        data = self._make_wft_request(WFT_BUILD_RESULTS_URL.format(build), WFT_HEADERS, WFT_BUILD_RESULTS_DATA)
        for result in data:
            storage = result.get('storage', {})
            if storage.get('title', '') != 'ARTIFACTORY':
                continue
            for storage_item in storage.get('storage-items', []):
                if storage_item.get('title', '').endswith(name):
                    return storage_item.get('path', '')
        self.logger.warning('Cannot find package {} for build {}'.format(name, build))
        return ''

    def get_similar_build(self, build_pattern: str) -> Optional[str]:
        """
        Retrieves a similar build based on a build pattern.

        Args:
            build_pattern (str): The build pattern to search for.

        Returns:
            Optional[str]: The similar build identifier, or None if not found.
        """
        req_data = dict(WFT_SIMILAR_BUILD_DATA)
        req_data["view_filters_attributes"]["0"]["value"] = build_pattern
        data = self._make_wft_request(WFT_BUILD_JSON_URL, WFT_HEADERS, req_data)
        return data.get("items")[0].get("version") if data.get("items") else None


